  "{count} kelime kopyalandı": {
    one: "{count} palavra-chave copiada",
    other: "{count} palavras-chave copiadas",
  },
  "Önce Ayarlar'da Google erişim anahtarını ya da hizmet hesabını girin. Sonra izleyeceğiniz siteyi seçin. Google buna mülk der. Siteyi yeni doğruladıysanız Google'ın veri vermesi birkaç gün sürebilir.":
    "Introduza primeiro a chave de acesso Google ou a conta de serviço nas Definições. Depois escolha o site a acompanhar; o Google chama-lhe uma propriedade. Se verificou o site há pouco tempo, o Google pode demorar alguns dias a disponibilizar dados.",
  "Search Console'daki Google erişim anahtarını kullanır, ayrı kurulum istemez. Bağlandıktan sonra Analytics'teki sitenizi (Analytics mülkü) seçin. Organik ziyaretler Panel'de ve Analytics ekranında görünür.":
    "Usa a mesma chave Google do Search Console, sem configuração adicional. Depois de ligar, selecione o seu site no Analytics (a propriedade do Analytics). As visitas orgânicas aparecem no Painel e no ecrã Analytics.",
  Genel: "Geral",
  "Ayar bölümleri": "Secções das definições",
  "Projeler yüklenemedi": "Não foi possível carregar os projetos",
  Bitti: "Concluído",
  Başarısız: "Falha",
  "Sitenizde düzeltmeniz gereken her şey, önem sırasına göre. Bir satıra tıklayın. Neden önemli olduğunu, nasıl düzelteceğinizi ve hangi sayfaların etkilendiğini adresleriyle görürsünüz.":
    "Tudo em seu site que precisa ser consertado, o mais importante primeiro. Clique em uma linha para ver por que isso é importante, como corrigi-lo e quais páginas foram afetadas, com seus endereços.",
  "Taranan her sayfa ve sunucunun ona verdiği yanıt. Hatalı, yavaş ya da derinde kalmış sayfaları buradan bulun.":
    "Cada página rastreada e como o servidor respondeu a ela. Encontre aqui páginas quebradas, lentas ou profundamente enterradas.",
  "Google bu sayfaları gerçekten dizinine almış mı? Almadıysa nedenini burada görürsünüz.":
    "O Google realmente indexou essas páginas? Caso contrário, você pode ver o motivo aqui.",
  "Sayfalarınız telefonda ve bilgisayarda ne kadar hızlı açılıyor? Ölçüm, Google'ın kullandığı Lighthouse ile yapılır.":
    "Qual a velocidade de carregamento de suas páginas em telefones e computadores? Medido com Lighthouse, a ferramenta que o Google usa.",
