  '<strong>{measured}</strong>{share}{failed}. Ortalama tek bir sayı "her sayfa orta" ile "yarısı mükemmel yarısı felaket"i aynı gösterdiği için dağılım veriliyor.':
    '<strong>{measured}</strong>{share}{failed}. A distribuição é mostrada porque uma única média faz com que "todas as páginas sejam justas" pareçam iguais a "metade excelente, metade péssima".',
  "{planned} sayfanın ölçülmesi planlandı, {measured} tanesi puan verdi{failed}. Aşağıdaki dağılım yalnızca ölçülen sayfaları yansıtır; ölçülmeyenler iyi ya da kötü sayılmadı.":
    "{planned} páginas foram planejadas para medição e {measured} retornaram uma pontuação {failed}. A distribuição abaixo reflete apenas as páginas medidas; o restante não foi considerado nem bom nem ruim.",
  "; kalanlar hata verdi ya da ölçüm servisinin istek sınırına takılmış olabilir":
    "; o restante falhou ou pode ter atingido o limite de solicitação do serviço de medição",
  "Ölçüm kısmi.": "Medição parcial.",
  "Mobil performans puanı dağılımı":
    "Distribuição de pontuação de desempenho móvel",
  "Lighthouse performans puanı histogramı":
    "Histograma de pontuação de desempenho do Lighthouse",
  "Puan bandı": "Faixa de pontuação",
  "İyi, orta, zayıf sayfa sayısı": "Página boa, média e ruim contagens",
  "Lighthouse kategorileri": "Categorias lighthouse",
  "Kategori başına mobil ortalama puan": "Pontuação média móvel por categoria",
  "Sayfa sayfa sonuçlar": "Resultados por página",
  "Mobil performans puanı en düşük sayfalar üstte. Metrikler mobil ölçümden.":
    "Páginas com a menor pontuação de desempenho móvel primeiro. As métricas são provenientes da medição móvel.",
  "<strong>Laboratuvar ve gerçek kullanıcı verisi.</strong> Buradaki rakamlar Lighthouse'un laboratuvar ölçümüdür: tek bir sanal cihazda, kontrollü ağ ve işlemci koşulunda yapılır. Gerçek ziyaretçilerden toplanan alan verisi (Chrome Kullanıcı Deneyimi Raporu, CrUX) bu denetimde saklanmadığı için rapora girmiyor. İkisi farklı çıkabilir. Google, sıralama sistemlerinde alan verisini (CrUX) kullanır; ama iyi bir değer tek başına sıralama garantisi vermez, içeriğin ilgili olması öncelik taşır.":
    "<strong>Dados de laboratório e dados de usuários reais.</strong> Esses números são medições de laboratório do Lighthouse, feitas em um único dispositivo simulado sob condições controladas de rede e CPU. Os dados de campo coletados de visitantes reais (Relatório de experiência do usuário do Chrome, CrUX) não são armazenados para esta auditoria e, portanto, não estão no relatório. Os dois podem ser diferentes. Os sistemas de classificação do Google usam dados de campo (CrUX), mas um bom valor por si só não garante classificações; o conteúdo relevante vem em primeiro lugar.",
  'Eşikler Google\'ın yayımladığı değerlerdir: LCP 2,5 sn altı iyi, 4 sn üstü zayıf; CLS 0,1 altı iyi, 0,25 üstü zayıf; INP 200 ms altı iyi, 500 ms üstü zayıf. INP laboratuvarda çoğu zaman ölçülemez ("--" görünür).':
    'Os limites são os valores publicados pelo Google: LCP abaixo de 2,5 s é bom e acima de 4 s é ruim; CLS abaixo de 0,1 é bom e acima de 0,25 é ruim; O INP abaixo de 200 ms é bom e acima de 500 ms é ruim. O INP muitas vezes não pode ser medido no laboratório (mostra "--").',
  "Her sürümde nelerin eklendiğini ve düzeltildiğini burada bulabilirsiniz.":
    "Veja o que foi adicionado e corrigido em cada versão.",
  Yenilik: "Recurso",
  Düzeltme: "Correção",
  "Acil düzeltme": "Hotfix",
  "Windows açılınca başlat": "Comece com Windows",
  "Windows ayarı kaydedildi": "Preferências do Windows salvas",
  "Bu tercihler Windows uygulamasına kaydedilir ve tepsi menüsüyle aynı ayarları kullanır.":
    "Essas preferências são salvas no aplicativo do Windows e compartilhadas com o menu da bandeja.",
  "Windows ayarları okunuyor…": "Leitura das preferências do Windows…",
  "Bu seçenekler Windows paketinde kullanılabilir. Docker veya geliştirici kurulumunda başlangıç davranışını işletim sisteminizden yönetin.":
    "Essas opções estão disponíveis no aplicativo do Windows. Para instalações do Docker ou de desenvolvimento, gerencie a inicialização por meio do sistema operacional.",
  "Bu Windows başlatıcısı uygulama içinden ayar değiştirmeyi desteklemiyor. Windows paketini güncelleyin; bu sırada tepsi menüsündeki seçenekleri kullanabilirsiniz.":
    "Este iniciador do Windows não oferece suporte à alteração de preferências do aplicativo. Atualize o pacote do Windows; até então, use as opções do menu da bandeja.",
  "Windows ayarlarına ulaşılamadı. Tepsi uygulamasının açık olduğunu kontrol edip yeniden deneyin.":
    "As preferências do Windows não estão disponíveis. Verifique se o aplicativo da bandeja está em execução e tente novamente.",
  "Windows oturumu açıldığında arka planda başlar. Kapalıyken uygulamayı kendiniz açarsınız.":
    "Começa em segundo plano quando você faz login no Windows. Quando desativado, você mesmo abre o aplicativo.",
  "Bu ayar yönetici tarafından tüm kullanıcılar için açılmış. Yalnızca yönetici kapatabilir.":
    "Um administrador ativou esta opção para todos os usuários. Somente um administrador pode desativá-lo.",
  "Otomatik güncelleme kurulumu": "Instalar atualizações automaticamente",
  "Yeni sürümü indirir, doğrular ve kurar. Kapalıyken tepsi menüsünden Güncelle seçeneğiyle kurabilirsiniz.":
    "Baixa, verifica e instala novas versões. Quando desativado, use Atualizar no menu da bandeja para instalá-los.",
  "Tüm kullanıcılar için kurulumda güncellemeyi yönetici kurar. Uygulama yeni sürümü haber verir.":
    "Para instalações para todos os usuários, um administrador instala as atualizações. O aplicativo notifica você sobre novos lançamentos.",
  "Tarayıcı sekmesini kapatmak uygulamayı durdurmaz. Tamamen kapatmak için tepsi menüsünden Çıkış deyin. Bilgisayar uyurken denetimler çalışmaz.":
    "Fechar a guia do navegador não interrompe o aplicativo. Para fechá-lo completamente, escolha Sair no menu da bandeja. As auditorias não são executadas enquanto o computador está em suspensão.",
  Görünüm: "Aparência",
  "Varsayılan koyu tema seowatcher.io ile aynı görünür. Sistem, işletim sisteminizin tercihini izler. Seçim bu tarayıcıda saklanır.":
    "O tema escuro padrão corresponde a seowatcher.io. O sistema segue a preferência do seu sistema operacional. Sua escolha é salva neste navegador.",
